python3 -c "
import json
with open('/app/resources/treasury_bulletin_2007_12.json', 'r') as f:
    data = json.load(f)

# Find all table elements and check for TIPS
for i, elem in enumerate(data['document']['elements']):
    if elem.get('type') == 'table':
        if elem.get('rows'):
            for row in elem['rows']:
                row_str = str(row)
                if '2-3/8% TIPS' in row_str:
                    print(f'Element {i}:')
                    print(f'Columns: {elem.get(\"columns\")}')
                    print(f'Found {len(elem[\"rows\"])} rows')
                    for r in elem['rows']:
                        if '2-3/8% TIPS' in str(r):
                            print(r)
                    break
"
